async function validate(){await refreshReadiness();showValidation()}
function showValidation(){
 const issues=describeCourseIssues(state.content,state.readiness?.errors||[],state.readiness?.warnings||[]),ar=document.documentElement.lang==='ar';
 const wrap=modal(t('Validation details'),`<p>${esc(t('Drafts can be saved while incomplete. Publishing requires every blocker to be resolved.'))}</p>${renderReadinessCategories()}<button class="btn" data-safe-repair>${esc(t('Repair generated identifiers'))}</button><div class="validation-issues">${issues.map((issue,index)=>`<article class="validation-issue"><div class="metric-row"><strong dir="auto">${esc(issue.location)}</strong><span class="badge">${esc(t(issue.severity==='blocker'?'Blocker':'Warning'))}</span></div><h3>${esc(ar?issue.cause_ar:issue.cause)}</h3><p dir="auto">${esc(issue.detail)}</p><div class="validation-repair"><strong>${esc(t('How to resolve'))}</strong><p>${esc(ar?issue.fix_ar:issue.fix)}</p></div>${issue.selection?`<button class="btn" data-open-issue="${index}">${esc(t('Open affected item'))}</button>`:''}</article>`).join('')||`<div class="empty">${esc(t('Ready to publish'))}</div>`}</div>`,{onConfirm:null,wide:true});
 wrap.querySelector('[data-safe-repair]')?.addEventListener('click',async()=>{const result=repairMechanicalIds(state.content,newId);if(!result.changes.length)return toast(t('No safe mechanical repairs are needed.'));remember();state.content=result.course;markDirty();await refreshReadiness();wrap.remove();showValidation();render()});wrap.querySelectorAll('[data-open-issue]').forEach(button=>button.onclick=()=>{state.selection=issues[Number(button.dataset.openIssue)].selection;state.tab='edit';wrap.remove();render()});
}
