  const input=document.createElement('input');input.type='file';input.accept='.pdf,.pptx,application/pdf,application/vnd.openxmlformats-officedocument.presentationml';
  input.onchange=async()=>{const file=input.files?.[0];if(!file)return;const lower=file.name.toLowerCase();if(!lower.endsWith('.pdf')&&!lower.endsWith('.pptx'))return toast(t('Choose a PDF or PPTX file.'),'error');
    try{const key=`assets/imported/${newId()}_${file.name.replace(/[^a-zA-Z0-9._-]+/g,'_')}`;const r=await api(`/api/course-versions/${state.version.id}/presentation-import`,{method:'POST',body:await file.arrayBuffer(),headers:{'X-File-Name':encodeURIComponent(file.name),'X-Asset-Key':key,'Content-Type':file.type||'application/octet-stream'}});const item=selected();item.content??={blocks:[]};item.content.blocks??=[];item.content.blocks.push(r.block);markDirty();render();toast(r.warnings?.length?`${t('Presentation imported.')} ${r.warnings.join(' ')}`:t('Presentation imported.'),'success')}catch(e){toast(t(e.message),'error')}};input.click();
