function arrOf(kind,mi){const m=moduleAt(mi);if(kind==='activity')return m.activities??=[];if(kind==='mission')return m.missions??=[];return m.paths??=[]}
function addItem(kind,mi){const a=arrOf(kind,mi);if(kind==='activity')a.push({id:`activity_${newId()}`,type:'presentation',title:'New activity',trainer:{cue:''},content:{blocks:[{type:'text',title:'',body_md:''}]},results_display:'cards'});else if(kind==='mission')a.push({id:`mission_${newId()}`,title:'New mission',goal:'',steps:[{id:newId(),title:'Step 1',body_md:'',completion:{type:'acknowledge'}}],submission:{type:'none'}});else a.push({id:`path_${newId()}`,guided:true,title:'New participant path',description:'',steps:[{id:newId(),title:'Step 1',body_md:'',completion:{type:'acknowledge'}}]});state.selection={kind,mi,ii:a.length-1};state.tab='edit';markDirty();render()}
function moveItem(kind,mi,i,d){const a=arrOf(kind,mi),j=d==='up'?i-1:i+1;if(j>=0&&j<a.length)[a[i],a[j]]=[a[j],a[i]];markDirty();render()}
