function collectSteps(x){x.steps.forEach((st,i)=>{if(st.use_template)return;const wrap=document.querySelector(`[data-guided-editor="${i}"]`);if(wrap){st.content??={blocks:st.blocks||[]};collectBlockEdits(st,wrap);st.optional=!!wrap.querySelector('[data-step-optional]')?.checked;st.interactions=[...wrap.querySelector('[data-step-interactions]').selectedOptions].map(x=>({activity_id:x.value}));delete st.interaction;}st.title=document.querySelector(`[data-step-title="${i}"]`)?.value||st.title;st.body_md=document.querySelector(`[data-step-body="${i}"]`)?.value||'';const pr=document.querySelector(`[data-step-prompt="${i}"]`)?.value||'';if(pr)st.prompt=pr;else delete st.prompt;st.completion={...(st.completion||{}),type:document.querySelector(`[data-step-completion="${i}"]`)?.value||'acknowledge'};const items=document.querySelector(`[data-completion-items="${i}"]`);if(items)st.completion.items=lines(items.value);const layout=document.querySelector(`[data-step-layout="${i}"]`);if(layout)st.layout=layout.value;const when=readCondition(wrap||document,'step-'+i);if(when)st.when=when;else if(wrap)delete st.when})}
function applyMission(silent=false){const m=selected();m.title=document.querySelector('#missionTitle').value.trim()||m.title;m.goal=document.querySelector('#missionGoal').value;m.submission={...(m.submission||{}),type:document.querySelector('#missionSubmission').value};const ach=document.querySelector('#missionAchievement').value.trim();if(ach)m.achievement={key:m.achievement?.key||`achievement_${newId()}`,title:ach};else delete m.achievement;collectSteps(m);markDirty();if(!silent){toast(t('Applied'),'success');render()}}
function applyPath(silent=false){const p=selected();collectPathContext(p);p.title=document.querySelector('#pathTitle').value.trim()||p.title;p.description=document.querySelector('#pathDescription').value;p.offline_fallback=typeof p.offline_fallback==='object'?{...p.offline_fallback,instructions:document.querySelector('#pathFallback').value}:document.querySelector('#pathFallback').value;const ach=document.querySelector('#pathAchievement').value.trim();if(ach)p.achievement={key:p.achievement?.key||`achievement_${newId()}`,title:ach};else delete p.achievement;collectSteps(p);markDirty();if(!silent){toast(t('Applied'),'success');render()}}
function autoWorkflow(){const m=moduleAt(state.selection.mi),wf=selected();wf.nodes=[];wf.edges=[];const classNodes=[];for(const a of m.activities||[]){const n={id:`wf_${a.id}`,type:activitySpec(a.type)?.participant_input?'class_interaction':'activity',title:a.title,activity_id:a.id};wf.nodes.push(n);classNodes.push(n)}for(let i=0;i<classNodes.length-1;i++)wf.edges.push({from:classNodes[i].id,to:classNodes[i+1].id,scope:'class'});let tail=classNodes.at(-1)||null;if((m.paths||[]).length){const practice={id:`wf_practice_${m.id}`,type:'practice_start',title:t('Start student activity')};wf.nodes.push(practice);if(tail)wf.edges.push({from:tail.id,to:practice.id,scope:'class'});const pathNodes=(m.paths||[]).map(pp=>({id:`wf_path_${pp.id}`,type:'participant_path',title:pp.title,path_id:pp.id}));wf.nodes.push(...pathNodes);for(const n of pathNodes)wf.edges.push({from:practice.id,to:n.id,scope:'participant',condition:{path_id:n.path_id}});const join={id:`wf_converge_${m.id}`,type:'convergence',title:t('Convergence')};wf.nodes.push(join);for(const n of pathNodes)wf.edges.push({from:n.id,to:join.id,scope:'participant'});tail=join}for(const x of m.missions||[]){const n={id:`wf_mission_${x.id}`,type:'mission',title:x.title,mission_id:x.id};wf.nodes.push(n);if(tail)wf.edges.push({from:tail.id,to:n.id,scope:'class'});tail=n}const close={id:`wf_close_${m.id}`,type:'closing',title:t('Closing')};wf.nodes.push(close);if(tail)wf.edges.push({from:tail.id,to:close.id,scope:'class'});wf.start_node_id=wf.nodes[0]?.id||'';markDirty();render()}
function applyWorkflow(){const wf=selected();wf.start_node_id=document.querySelector('#workflowStart').value;wf.nodes.forEach((n,i)=>{n.title=document.querySelector(`[data-wf-title="${i}"]`)?.value||n.title;n.type=document.querySelector(`[data-wf-type="${i}"]`)?.value||n.type;const aid=document.querySelector(`[data-wf-activity="${i}"]`)?.value||'',mid=document.querySelector(`[data-wf-mission="${i}"]`)?.value||'',pid=document.querySelector(`[data-wf-path="${i}"]`)?.value||'';if(aid)n.activity_id=aid;else delete n.activity_id;if(mid)n.mission_id=mid;else delete n.mission_id;if(pid)n.path_id=pid;else delete n.path_id;if(document.querySelector(`[data-wf-terminal="${i}"]`)?.checked)n.terminal=true;else delete n.terminal});wf.edges.forEach((e,i)=>{e.from=document.querySelector(`[data-wf-from="${i}"]`)?.value||e.from;e.to=document.querySelector(`[data-wf-to="${i}"]`)?.value||e.to;e.scope=document.querySelector(`[data-wf-scope="${i}"]`)?.value||'class';const mode=document.querySelector(`[data-edge-rule="${i}"]`)?.value;if(mode==='path')e.condition={path_id:document.querySelector(`[data-edge-path="${i}"]`).value};else if(mode==='always')delete e.condition});markDirty();toast(t('Applied'),'success');render()}
