function guidedPreviewState(){state.guidedSessions??={};return state.guidedSessions[state.previewModule]??={pathId:null,index:0,progress:{steps:{}},responses:{},status:'working'}}
function bindGuidedPreview(){if(state.previewMode!=='participant'||state.tab!=='preview')return;const module=mods()[state.previewModule]||mods()[0],session=guidedPreviewState(),path=module?.paths?.find(p=>p.id===session.pathId);bindGuided(document.querySelector('.guided-preview'),{path,module,progress:session.progress,stepIndex:session.index,responses:session.responses,onUpload:async file=>({id:1,name:file.name}),onChoose:id=>{Object.assign(session,{pathId:id,index:0,progress:{steps:{}},responses:{},status:'working'});render()},onSave:async data=>{session.progress.steps[stepKey(expandPath(module,path).steps[session.index],session.index)]=structuredClone(data)},onNavigate:async(action,data)=>{session.progress.steps[stepKey(expandPath(module,path).steps[session.index],session.index)]=structuredClone(data);if(action==='finish')session.status='finished';else session.index=Math.max(0,Math.min(path.steps.length-1,session.index+(action==='back'?-1:1)));render()},onResponse:async(id,value)=>{session.responses[id]={value};return {value}},onResponseSaved:async()=>render()});document.querySelector('#guidedRestart')?.addEventListener('click',()=>{delete state.guidedSessions[state.previewModule];render()});for(const [id,key] of [['guidedWidth','guidedWidth'],['guidedDirection','guidedDirection']])document.getElementById(id)?.addEventListener('change',e=>{state[key]=e.target.value;render()})}
function guidedStepExtras(st,i){const module=moduleAt(state.selection.mi);return `<div data-guided-editor="${i}">${extendedStepProperties(st,i)}<label class="selection-card"><input type="checkbox" data-step-optional="${i}" ${st.optional?'checked':''}>${esc(t('Optional'))}</label><label class="field"><span>${esc(t('Embedded questions'))}</span><select class="select" multiple data-step-interactions="${i}">${(module.activities||[]).filter(a=>GUIDED_INTERACTIONS.includes(a.type)).map(a=>`<option value="${esc(a.id)}" ${[st.interaction?.activity_id,...(st.interactions||[]).map(x=>x.activity_id)].includes(a.id)?'selected':''}>${esc(a.title)}</option>`).join('')}</select></label><h4>${esc(t('Guided blocks'))}</h4>${(st.content?.blocks||st.blocks||[]).map(blockEditor).join('')}<div class="form-actions"><select class="select" data-guided-block-type="${i}">${blockTypes.map(k=>`<option value="${k}">${esc(componentLabel(k,'content_blocks'))}</option>`).join('')}</select><button class="btn" data-guided-add-block="${i}">${esc(t('Add block'))}</button>${state.selection.kind==='shared'?'':`<button class="btn" data-guided-duplicate="${i}">${esc(t('Duplicate'))}</button><button class="btn" data-guided-reorder="${i}" data-direction="-1">↑</button><button class="btn" data-guided-reorder="${i}" data-direction="1">↓</button>`}</div></div>`}
function bindGuidedEditor(){document.querySelectorAll('[data-guided-add-block],[data-guided-duplicate],[data-guided-reorder]').forEach(el=>el.addEventListener('click',()=>{const path=state.selection.kind==='shared'?{steps:[selected()]}:selected();collectSteps(path);remember();if(el.dataset.guidedAddBlock!==undefined){const i=Number(el.dataset.guidedAddBlock),step=path.steps[i];step.content??={blocks:step.blocks||[]};step.content.blocks??=[];const type=document.querySelector(`[data-guided-block-type="${i}"]`).value;step.content.blocks.push({...newBlock(type),id:newId()})}else if(el.dataset.guidedDuplicate!==undefined){const i=Number(el.dataset.guidedDuplicate),step=structuredClone(path.steps[i]);step.id=newId();cloneStepQuestions(step,moduleAt(state.selection.mi));for(const b of step.content?.blocks||step.blocks||[])if(b.id)b.id=newId();path.steps.splice(i+1,0,step)}else{const i=Number(el.dataset.guidedReorder),j=i+Number(el.dataset.direction);if(j>=0&&j<path.steps.length)[path.steps[i],path.steps[j]]=[path.steps[j],path.steps[i]]}markDirty();render()}))}

function blockTarget(el){if(state.selection.kind==='shared')return {content:(selected().content??={blocks:[]})};const wrap=el.closest('[data-guided-editor]');if(!wrap)return selected();const step=selected().steps[Number(wrap.dataset.guidedEditor)];step.content??={blocks:step.blocks||[]};return step}

function oldGuidedStepPreset(kind){const id=newId(),base={id,title:t(({instruction:'Instruction',prompt_task:'Prompt task',source_review:'Source review',reflection:'Reflection',evaluation:'Evaluation',completion:'Completion'})[kind]||'Step'),body_md:'',content:{blocks:[]},completion:{type:'acknowledge'}};if(kind==='prompt_task')base.content.blocks=[{id:newId(),type:'prompt',title:t('Prompt'),prompt:t('Write the prompt for this learning task.')}];if(kind==='source_review')base.content.blocks=[{type:'resource_list',items:[]}];if(kind==='reflection')base.completion={type:'text'};if(kind==='evaluation')base.completion={type:'none'};return base}

async function exportCourse(){while(state.saving)await new Promise(resolve=>setTimeout(resolve,25));await save({quiet:true});if(state.dirty)throw new Error(t('Save your latest changes before publishing or exporting.'));const response=await fetch(`/api/course-versions/${state.version.id}/export`,{headers:{'X-Session-Token':getToken()}});if(!response.ok){const result=await response.json();throw new Error(t(result.message||'Course export failed.'))}const url=URL.createObjectURL(await response.blob()),link=document.createElement('a');link.href=url;link.download='course-package.course.zip';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast(t('Course package exported.'),'success')}

// getRandomValues works on ordinary LAN HTTP as well as secure localhost.
function newId(){return Array.from(crypto.getRandomValues(new Uint8Array(16)),n=>n.toString(16).padStart(2,'0')).join('')}

const STEP_TITLES={instruction:'Instruction',tool_setup:'Tool setup',prompt_task:'Prompt task',source_review:'Source review',choice:'Choice',verify:'Verify',reflection:'Reflection',assessment:'Assessment',evaluation:'Evaluation',completion:'Completion'};
