function variableInput(value,type=typeof value){return type==='boolean'?`<input type="checkbox" data-variable-value ${value?'checked':''}>`:`<input class="input" dir="auto" type="${type==='number'?'number':'text'}" ${type==='number'?'step="any"':''} data-variable-value value="${esc(value??'')}">`}
function variableFields(scope,variables={}){return `<section class="card flat" data-variable-scope="${scope}"><div class="metric-row"><h3>${esc(t(scope==='module'?'Milestone variables':'Path variables'))}</h3><button class="btn" type="button" data-add-variable="${scope}">${esc(t('Add variable'))}</button></div>${Object.entries(variables).map(([name,value],i)=>`<div class="variable-row form-grid"><label class="field"><span>${esc(t('Variable name'))}</span><input class="input" dir="ltr" data-variable-name value="${esc(name)}"></label><label class="field"><span>${esc(t('Value type'))}</span><select class="select" data-variable-type>${['string','number','boolean'].map(type=>`<option value="${type}" ${typeof value===type?'selected':''}>${esc(t({string:'Text',number:'Number',boolean:'Boolean'}[type]))}</option>`).join('')}</select></label><label class="field" data-variable-value-wrap><span>${esc(t('Value'))}</span>${variableInput(value)}</label><button class="btn danger" type="button" data-remove-variable="${scope}" data-variable-index="${i}">${esc(t('Delete'))}</button></div>`).join('')}</section>`}

function guidedLibrary(path){const module=moduleAt(state.selection.mi);return `<section class="card flat"><h3>${esc(t('Path presentation'))}</h3><div class="form-grid">${[['goal','Goal'],['eyebrow','Eyebrow'],['icon','Icon'],['image_asset','Local image'],['metadata','Choice metadata']].map(([key,label])=>`<label class="field"><span>${esc(t(label))}</span><input class="input" data-path-property="${key}" value="${esc(path[key]||'')}"></label>`).join('')}</div></section><details class="card creator-library"><summary>${esc(t('Variables and shared steps'))}</summary><p>${esc(t('Shared changes apply to every reference. Each use keeps its own progress identity.'))}</p>${variableFields('module',module.variables)}${variableFields('path',path.variables)}<div class="metric-row"><h3>${esc(t('Shared steps'))}</h3><button class="btn" type="button" data-new-shared>${esc(t('New shared step'))}</button></div>${Object.entries(module.step_templates||{}).map(([key,x])=>`<div class="list-row"><strong>${esc(x.title||t('Shared step'))}</strong><button class="btn" type="button" data-edit-shared="${esc(key)}">${esc(t('Edit'))}</button><button class="btn danger" type="button" data-delete-shared="${esc(key)}">${esc(t('Delete'))}</button></div>`).join('')}</details>`}
function collectPathContext(path){if(document.querySelector('#pathTitle')){path.title=document.querySelector('#pathTitle').value.trim()||path.title;path.description=document.querySelector('#pathDescription').value;}const module=moduleAt(state.selection.mi);document.querySelectorAll('[data-path-property]').forEach(el=>path[el.dataset.pathProperty]=el.value);for(const scope of ['module','path']){const root=document.querySelector(`[data-variable-scope="${scope}"]`);if(!root)continue;const entries=[...root.querySelectorAll('.variable-row')].map(row=>{const type=row.querySelector('[data-variable-type]').value,input=row.querySelector('[data-variable-value]'),value=type==='boolean'?input.checked:type==='number'?Number(input.value):input.value;if(type==='number'&&!Number.isFinite(value))throw new Error(t('Enter a finite number for this variable.'));return [row.querySelector('[data-variable-name]').value.trim(),value]});if(entries.some(([k])=>! /^[a-zA-Z][\w-]*$/.test(k)||['constructor','prototype','__proto__','selected_path','selected_path_title','path_goal'].includes(k))||new Set(entries.map(([k])=>k)).size!==entries.length)throw new Error(t('Use unique variable names beginning with a letter.'));(scope==='module'?module:path).variables=Object.fromEntries(entries)}}
function sharedReferenceEditor(step,i){const module=moduleAt(state.selection.mi),template=module.step_templates?.[step.use_template];return `<article class="builder-step"><span class="badge">${esc(t('Shared step'))}</span><h3>${esc(template?.title||t('Missing shared step'))}</h3><div class="form-actions"><button class="btn" data-edit-shared="${esc(step.use_template)}">${esc(t('Edit shared definition'))}</button><button class="btn" data-detach-shared="${i}">${esc(t('Make independent'))}</button><button class="btn" data-guided-reorder="${i}" data-direction="-1">↑</button><button class="btn" data-guided-reorder="${i}" data-direction="1">↓</button><button class="btn danger" data-step-delete="${i}">${esc(t('Delete'))}</button></div></article>`}
