function guidedStepPreset(kind){const base={id:newId(),title:t(STEP_TITLES[kind]||'Step'),layout:kind==='prompt_task'?'prompt_task':kind==='reflection'?'reflection':'standard',body_md:'',content:{blocks:[]},completion:{type:'acknowledge'}};const prompt=()=>({...newBlock('prompt'),title:t('Prompt'),prompt:t('Write the prompt for this learning task.')});if(['prompt_task','verify'].includes(kind))base.content.blocks=[prompt(),{...newBlock('checklist'),items:[{title:t('Check your evidence'),body_md:''}]}];if(kind==='instruction')base.content.blocks=[{...newBlock('checklist'),items:[{title:t('Read the instructions'),body_md:''}]}];if(['source_review','tool_setup'].includes(kind))base.content.blocks=[{...newBlock('resource_list'),items:[]},...(kind==='tool_setup'?[{...newBlock('steps'),items:[{title:t('Open the tool'),body_md:''},{title:t('Return to your class'),body_md:''}]}]:[])];if(kind==='choice')base.content.blocks=[{...newBlock('cards'),items:[{title:t('Option A'),body_md:''},{title:t('Option B'),body_md:''}]}];if(kind==='reflection')base.completion={type:'text'};if(['assessment','evaluation','completion'].includes(kind))base.completion={type:'none'};return base}
function branchDesigner(module){return `<section class="card flat branch-designer"><h3>${esc(t('Connect learning paths'))}</h3><p>${esc(t('Select the choices, introduction and closing. This creates explicit branch connections and a shared convergence.'))}</p><div class="form-grid">${(module.paths||[]).map(p=>`<label class="selection-card"><input type="checkbox" data-connect-path="${esc(p.id)}" checked><strong>${esc(p.title)}</strong></label>`).join('')}<label class="field"><span>${esc(t('Introduction'))}</span><select class="select" data-branch-intro><option value="">${esc(t('None'))}</option>${(module.activities||[]).map(a=>`<option value="${esc(a.id)}">${esc(a.title)}</option>`).join('')}</select></label><label class="field"><span>${esc(t('Closing activity'))}</span><select class="select" data-branch-close><option value="">${esc(t('None'))}</option>${(module.activities||[]).map(a=>`<option value="${esc(a.id)}">${esc(a.title)}</option>`).join('')}</select></label></div><button class="btn primary" data-connect-branches>${esc(t('Create branch connections'))}</button></section>`}
function renderFlowGraph(module){if(!module)return '';if(!module.workflow?.nodes?.length)return `<div class="workflow-canvas">${[...(module.activities||[]),...(module.paths||[]),...(module.missions||[])].map(x=>`<div class="workflow-node-card"><strong>${esc(x.title)}</strong></div>`).join('<div class="workflow-arrow">↓</div>')}</div>`;const r=simulateRoutes(module),wf=module.workflow,levels=new Map([[wf.start_node_id,0]]),queue=[wf.start_node_id];for(let i=0;i<queue.length;i++){const id=queue[i];for(const e of wf.edges||[])if(e.from===id&&!levels.has(e.to)){levels.set(e.to,(levels.get(id)||0)+1);queue.push(e.to)}}const rank=id=>levels.get(id)??Math.max(0,...levels.values())+1,names=new Map(wf.nodes.map(n=>[n.id,n.title||resolveRefTitle(module,n)||t('Section')]));return `<section class="creator-flow" aria-label="${esc(t('Workflow'))}">${[...new Set(wf.nodes.map(n=>rank(n.id)))].sort((a,b)=>a-b).map(level=>`<div class="flow-rank">${wf.nodes.filter(n=>rank(n.id)===level).map(n=>`<article class="workflow-node-card ${r.invalid_nodes.includes(n.id)?'invalid':''}"><span class="badge">${esc(componentLabel(n.type,'workflow_nodes'))}</span><strong>${esc(names.get(n.id))}</strong>${n.id===wf.start_node_id?`<span>${esc(t('Start'))}</span>`:''}${n.terminal||n.type==='closing'?`<span>${esc(t('Terminal'))}</span>`:''}${r.invalid_nodes.includes(n.id)?`<span role="status">${esc(t('Needs repair'))}</span>`:''}</article>`).join('')}</div>`).join('<div class="workflow-arrow" aria-hidden="true">↓</div>')}<ol class="flow-connections">${(wf.edges||[]).map(e=>`<li class="${!names.has(e.from)||!names.has(e.to)?'invalid':''}"><strong>${esc(names.get(e.from)||t('Missing section'))}</strong> → <strong>${esc(names.get(e.to)||t('Missing section'))}</strong> <span class="badge">${esc(t(e.scope==='participant'?'Participant':'Class'))}</span>${e.condition?`<span>${esc(t('Conditional'))}${e.condition.path_id?': '+esc(module.paths?.find(p=>p.id===e.condition.path_id)?.title||t('Missing path')):''}</span>`:''}</li>`).join('')}</ol></section>`}
function renderReadinessCategories(){return `<div class="readiness-grid">${readinessCategories(state.readiness?.errors,state.readiness?.warnings).map(c=>`<article class="card flat"><strong>${esc(t(c.name))}</strong><span class="badge">${esc(t(c.status==='REVIEW'?'Review in preview':c.status))}</span></article>`).join('')}</div>`}
function bindCreatorClosure(){
 document.querySelectorAll('[data-variable-type]').forEach(select=>select.onchange=()=>{const row=select.closest('.variable-row'),old=row.querySelector('[data-variable-value]'),value=old.type==='checkbox'?old.checked:old.value,type=select.value;row.querySelector('[data-variable-value-wrap]').innerHTML=`<span>${esc(t('Value'))}</span>${variableInput(type==='boolean'?value===true||value==='true':type==='number'?Number(value)||0:String(value),type)}`});
 document.querySelectorAll('.builder-block').forEach(article=>{article.addEventListener('focusin',e=>{if(e.target.matches('textarea[data-bprop],input[type=text][data-bprop]'))article.variableTarget=e.target});article.querySelector('[data-insert-context]')?.addEventListener('click',()=>{const target=article.variableTarget||article.querySelector('textarea[data-bprop],input[type=text][data-bprop]');if(!target)return;target.setRangeText('${'+article.querySelector('[data-context-variable]').value+'}',target.selectionStart??target.value.length,target.selectionEnd??target.value.length,'end');target.focus()})});
 document.querySelectorAll('[data-condition-question]').forEach(el=>el.addEventListener('change',()=>refreshConditionInspector(el)));
 document.querySelectorAll('[data-condition-mode]').forEach(el=>{const update=()=>{const fieldset=el.closest('fieldset');for(const [key,visible] of [['path',el.value==='path'],['question',el.value==='response'],['operator',el.value==='response'],['value',el.value==='response']]){const label=fieldset.querySelector(`[data-condition-${key}]`)?.closest('label');if(label)label.hidden=!visible}};el.addEventListener('change',update);update()});
 document.querySelectorAll('details.builder-step').forEach(el=>el.ontoggle=()=>{if(el.open)state.openStep=Number(el.dataset.stepIndex)});
 const mutate=fn=>{try{remember();fn();markDirty();render()}catch(e){toast(t(e.message),'error')}};
 document.querySelectorAll('[data-prop-add],[data-prop-remove],[data-grid-add-column],[data-grid-add-row],[data-grid-remove-column],[data-grid-remove-row]').forEach(button=>button.onclick=()=>mutate(()=>{const target=blockTarget(button);collectBlockEdits(target,button.closest('[data-guided-editor]')||document);const i=Number(button.closest('[data-block-index]').dataset.blockIndex);changeBlockCollection(button,target.content.blocks[i])}));
 document.querySelectorAll('[data-add-variable],[data-remove-variable]').forEach(button=>button.onclick=()=>mutate(()=>{const path=selected();collectPathContext(path);collectSteps(path);const scope=button.dataset.addVariable||button.dataset.removeVariable,obj=scope==='module'?moduleAt(state.selection.mi):path;obj.variables??={};if(button.dataset.addVariable){let i=Object.keys(obj.variables).length+1;while(Object.hasOwn(obj.variables,'value_'+i))i++;obj.variables['value_'+i]=''}else delete obj.variables[Object.keys(obj.variables)[Number(button.dataset.variableIndex)]]}));
 document.querySelectorAll('[data-edit-shared]').forEach(button=>button.onclick=()=>{state.returnPath=state.selection.kind==='path'?{...state.selection}:state.returnPath;state.selection={kind:'shared',mi:state.selection.mi,key:button.dataset.editShared};render()});
 document.querySelectorAll('[data-new-shared],[data-save-shared]').forEach(button=>button.onclick=()=>mutate(()=>{const path=selected();collectSteps(path);collectPathContext(path);const module=moduleAt(state.selection.mi),key='shared_'+newId(),index=Number(button.dataset.saveShared),definition=button.dataset.saveShared!==undefined?structuredClone(path.steps[index]):guidedStepPreset('instruction');delete definition.id;module.step_templates??={};module.step_templates[key]=definition;if(button.dataset.saveShared!==undefined)path.steps[index]={id:path.steps[index].id,use_template:key};state.returnPath={...state.selection};state.selection={kind:'shared',mi:state.selection.mi,key}}));
 document.querySelectorAll('[data-use-shared]').forEach(el=>el.onchange=()=>{if(!el.value)return;mutate(()=>{const path=selected();collectSteps(path);path.steps[Number(el.dataset.useShared)]={id:path.steps[Number(el.dataset.useShared)].id,use_template:el.value}})});
 document.querySelectorAll('[data-detach-shared]').forEach(button=>button.onclick=()=>mutate(()=>{const path=selected(),i=Number(button.dataset.detachShared),step=expandPath(moduleAt(state.selection.mi),path).steps[i];delete step.use_template;delete step.overrides;path.steps[i]=step}));
 document.querySelectorAll('[data-delete-shared]').forEach(button=>button.onclick=()=>mutate(()=>{const module=moduleAt(state.selection.mi),key=button.dataset.deleteShared;if(module.paths.some(p=>p.steps?.some(s=>s.use_template===key)))throw new Error(t('This shared step is still in use. Make its uses independent first.'));delete module.step_templates[key]}));
 document.querySelector('[data-apply-shared]')?.addEventListener('click',()=>mutate(()=>collectSteps({steps:[selected()]})));
 document.querySelector('[data-return-path]')?.addEventListener('click',()=>{state.selection=state.returnPath||{kind:'module',mi:state.selection.mi};render()});
 document.querySelector('[data-connect-branches]')?.addEventListener('click',()=>{if(!confirm(t('Replace this draft workflow with the selected branch connections?')))return;mutate(()=>{const module=moduleAt(state.selection.mi);module.workflow=connectParticipantBranches(module,[...document.querySelectorAll('[data-connect-path]:checked')].map(el=>el.dataset.connectPath),newId,{entryActivityId:document.querySelector('[data-branch-intro]').value||null,closingActivityId:document.querySelector('[data-branch-close]').value||null})})});
}

function configurePresetActivities(step,kind,module){if(!['choice','assessment','evaluation'].includes(kind))return;module.activities??=[];const add=(type,title,content)=>{const activity={id:'question_'+newId(),type,title,content};module.activities.push(activity);return {activity_id:activity.id}};if(kind==='evaluation'){const titles=['Clarity','Ease of the steps','Usefulness','Value of source verification','Value of the tool','Best part','Hardest part','Overall rating','Improvement suggestion','Most useful learning'];step.interactions=titles.map((title,i)=>add(i<5||i===7?'rating':i<7?'single_choice':'long_answer',t(title),i<5||i===7?{question:t(title),min:1,max:5,step:1}:i<7?{question:t(title),options:[t('Sources'),t('Prompt'),t('Practice')]}:{question:t(title)}))}else step.interaction=add(kind==='choice'?'single_choice':'short_answer',t(kind==='choice'?'Choose an option':'Check your understanding'),kind==='choice'?{question:t('Choose an option'),options:[t('Option A'),t('Option B')]}:{question:t('Check your understanding')})}
function showComponentPlayground(){const examples=[{type:'prompt',title:t('Short prompt'),prompt:'Explain with a citation.'},{type:'prompt',title:t('Long prompt'),prompt:'تحقق من المصدر. Verify the source. '.repeat(200)},{type:'editable_prompt',id:'playground-edit',title:t('Editable prompt'),template:'اكتب فكرتك / Write your idea'},{type:'cards',title:t('Two choices'),items:[{title:'A',body_md:'One route / مسار أول'},{title:'B',body_md:'Another route / مسار آخر'}]},{type:'cards',title:t('Three cards'),items:[{title:'A'},{title:'B'},{title:'C'}]},{type:'resource_list',title:t('Resources'),items:[{title:'UNESCO',organization:'UNESCO',resource_type:'web',url:'https://www.unesco.org/',description:t('Open a source and return to your class.')}]}];const w=modal(t('Component playground'),`<p>${esc(t('These temporary examples use the same renderer as the Participant.'))}</p>${renderContent({blocks:examples},{versionId:state.version.id})}${renderGuidedInteraction({id:'playground-rating',type:'rating',title:t('Rating'),content:{question:t('How would you rate this?'),min:1,max:5,step:1}})}`,{wide:true});bindContent(w);w.querySelector('form').onsubmit=e=>{e.preventDefault();w.querySelector('form [role=status]').textContent=t('Preview only. No classroom response was saved.')};}

function workflowConditionProperties(edge,module,i){const mode=edge.condition?.path_id?'path':edge.condition?'preserve':'always';return `<label class="field"><span>${esc(t('Branch rule'))}</span><select class="select" data-edge-rule="${i}">${mode==='preserve'?`<option value="preserve">${esc(t('Existing activity branch rule'))}</option>`:''}<option value="always" ${mode==='always'?'selected':''}>${esc(t('Always'))}</option><option value="path" ${mode==='path'?'selected':''}>${esc(t('Selected path'))}</option></select></label><label class="field"><span>${esc(t('Path'))}</span><select class="select" data-edge-path="${i}">${(module.paths||[]).map(p=>`<option value="${esc(p.id)}" ${edge.condition?.path_id===p.id?'selected':''}>${esc(p.title)}</option>`).join('')}</select></label>`}

function variableInsertionControl(){if(!['path','shared'].includes(state.selection?.kind))return '';const module=moduleAt(state.selection?.mi),path=state.selection?.kind==='path'?selected():state.returnPath?module?.paths?.[state.returnPath.ii]:null,variables=[...new Set(['path_goal','selected_path_title',...Object.keys(module?.variables||{}),...Object.keys(path?.variables||{})])];return `<div class="form-actions"><label class="field"><span>${esc(t('Insert variable'))}</span><select class="select" data-context-variable>${variables.map(key=>`<option value="${esc(key)}">${esc(key==='path_goal'?t('Path goal'):key==='selected_path_title'?t('Path title'):key)}</option>`).join('')}</select></label><button class="btn" type="button" data-insert-context>${esc(t('Insert into selected field'))}</button></div>`}

function cloneStepQuestions(step,module){const replacements=new Map();for(const id of [step.interaction?.activity_id,...(step.interactions||[]).map(x=>x.activity_id)].filter(Boolean)){if(replacements.has(id))continue;const source=module.activities.find(a=>a.id===id);if(!source)continue;const copy=structuredClone(source);copy.id='question_'+newId();module.activities.push(copy);replacements.set(id,copy.id)}const walk=value=>{if(!value||typeof value!=='object')return;for(const [key,child] of Object.entries(value))if(key==='activity_id'&&replacements.has(child))value[key]=replacements.get(child);else if(typeof child==='object')walk(child)};walk(step)}

function builderGuide(){return `<section class="builder-guide card flat"><div><h2>${esc(t('Build your course in three steps'))}</h2><p>${esc(t('Add a lesson, preview the learner experience, then review and publish.'))}</p></div><div class="form-actions"><button class="btn primary" data-builder-add-lesson>1 · ${esc(t('Add lesson'))}</button><button class="btn" data-tab="preview">2 · ${esc(t('Preview'))}</button><button class="btn" data-a="validate">3 · ${esc(t('Review'))}</button></div></section>`}
function starterPanel(){return `<section class="card builder-starter"><div class="eyebrow">${esc(t('Course Builder'))}</div><h2>${esc(t('Create your first lesson'))}</h2><p>${esc(t('Start with your teaching content and a practical task. We connect the presentation, participant practice, reflection and closing for you.'))}</p>${starterFields()}<button class="btn primary" data-create-starter>${esc(t('Create lesson'))}</button></section>`}
function starterFields(){return `<div class="form-grid"><label class="field span-2"><span>${esc(t('Lesson name'))}</span><input class="input" data-start-title required></label><label class="field span-2"><span>${esc(t('Teaching content'))}</span><textarea class="textarea" data-start-body rows="6" required></textarea></label><label class="field span-2"><span>${esc(t('Participant task'))}</span><textarea class="textarea" data-start-task rows="3"></textarea></label><label class="field span-2"><span>${esc(t('Reflection question'))}</span><input class="input" data-start-question placeholder="${esc(t('What is the most useful thing you learned?'))}"></label><label class="field"><span>${esc(t('Duration (minutes)'))}</span><input class="input" type="number" min="1" max="480" value="20" data-start-duration></label></div>`}
async function addStarter(root){const lesson=createStarterLesson({title:root.querySelector('[data-start-title]').value,body:root.querySelector('[data-start-body]').value,task:root.querySelector('[data-start-task]').value,question:root.querySelector('[data-start-question]').value,duration:root.querySelector('[data-start-duration]').value},newId,key=>tForLocale(key,state.content.course.language));remember();mods().push(lesson);state.selection={kind:'activity',mi:mods().length-1,ii:0};state.tab='edit';markDirty();render();await save({quiet:true});toast(t('Lesson created. Your presentation and practice are connected.'),'success')}
function builderOutline(){return `<details class="builder-outline card flat" ${globalThis.matchMedia?.('(min-width:900px)').matches?'open':''}><summary>${esc(t('Course outline'))}</summary><p class="small muted">${esc(t('Edits save automatically. Choose any item to continue.'))}</p><nav aria-label="${esc(t('Course outline'))}">${mods().map((m,mi)=>`<button class="outline-milestone" data-select="module" data-mi="${mi}">${esc(m.title||t('Milestone'))}</button>${[['activity',m.activities||[]],['path',m.paths||[]],['mission',m.missions||[]]].map(([kind,items])=>items.map((item,ii)=>`<button class="${state.selection?.mi===mi&&state.selection?.ii===ii&&state.selection?.kind===kind?'active':''}" data-select="${kind}" data-mi="${mi}" data-ii="${ii}">${esc(item.title||t('Untitled'))}</button>`).join('')).join('')}`).join('')}</nav><button class="btn" data-builder-add-lesson>${esc(t('Add lesson'))}</button></details>`}
function collectCurrentEditor(){if(state.tab!=='edit'||!selected())return;const kind=state.selection.kind;if(kind==='module'&&document.querySelector('#modTitle'))applyModule(true);else if(kind==='activity'&&document.querySelector('#actTitle'))applyActivity(true);else if(kind==='path'&&document.querySelector('#pathTitle'))applyPath(true);else if(kind==='mission'&&document.querySelector('#missionTitle'))applyMission(true)}
function bindBuilderEase(){
 organizeActivityEditor();
 document.querySelector('[data-create-starter]')?.addEventListener('click',async()=>{try{await addStarter(document.querySelector('.builder-starter'))}catch(e){toast(t(e.message),'error')}});
 document.querySelectorAll('[data-builder-add-lesson]').forEach(button=>button.onclick=()=>modal(t('Add lesson'),starterFields(),{confirmText:t('Create lesson'),wide:true,onConfirm:async root=>{await addStarter(root)}}));
 if(!app.dataset.builderEase){app.dataset.builderEase='1';app.addEventListener('focusin',e=>{if(e.target.closest('.builder-editor-stage')&&e.target.matches('input,textarea,select'))remember()});const sync=e=>{if(!e.target.closest('.builder-editor-stage')||!app.contains(e.target)||e.target.type==='file')return;try{collectCurrentEditor();updateBuilderLabels();updateBuilderStatus()}catch{markDirtyWithoutAutosave();updateBuilderStatus()}};app.addEventListener('input',sync);app.addEventListener('change',sync);
 app.addEventListener('click',e=>{if(!e.target.closest('[data-select],[data-tab],[data-a="save"],[data-a="publish"],[data-a="export-course"],[data-a="back-trainer"]'))return;try{collectCurrentEditor()}catch(err){e.preventDefault();e.stopImmediatePropagation();toast(t(err.message),'error')}},{capture:true});
 }
}

function organizeActivityEditor(){
 if(state.selection?.kind!=='activity'||state.tab!=='edit')return;const stage=document.querySelector('.builder-editor-stage>section');if(!stage)return;
 const advanced=document.createElement('details');advanced.className='card flat builder-advanced';advanced.innerHTML=`<summary>${esc(t('Advanced settings'))}</summary><p class="muted small">${esc(t('Trainer notes, result views, timing and navigation are optional.'))}</p><div class="form-grid" data-advanced-fields></div>`;
 for(const id of ['actResults','actCue']){const field=stage.querySelector('#'+id)?.closest('.field');if(field)advanced.querySelector('[data-advanced-fields]').append(field)}
 for(const id of ['actChallengeEnabled','actNext']){const section=stage.querySelector('#'+id)?.closest('section.card.flat');if(section)advanced.append(section)}
 const empty=stage.querySelector('.activity-type-settings');if(empty&&!empty.querySelector('input,textarea,select'))empty.remove();
 const actions=stage.querySelector(':scope>.form-actions');stage.insertBefore(advanced,actions||null);
}
function updateBuilderLabels(){const current=selected();if(!current)return;const title=document.querySelector('.builder-editor-stage>section>.page-head h2');if(title)title.textContent=current.title||'';for(const button of document.querySelectorAll('.builder-outline [data-select]')){const m=moduleAt(button.dataset.mi),kind=button.dataset.select,item=kind==='module'?m:(kind==='activity'?m?.activities:kind==='path'?m?.paths:m?.missions)?.[Number(button.dataset.ii)];if(item)button.textContent=item.title||t('Untitled')}}
